contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint creditBefore = depositAmount;
        uint balBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool creditZero = creditBefore == 0;
        if (reverted) {
            creditZero = creditBefore == 0;
        } else {
            creditZero = true;
        }

        bool balanceConsistent = false;
        if (reverted) {
            balanceConsistent = address(c).balance == balBefore;
        } else {
            balanceConsistent = address(c).balance == balBefore - creditBefore;
        }

        assert(creditZero && balanceConsistent);
    }

    receive() external payable {}
}

